def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    for color in {v for row in grid for v in row if v}:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        top = min(r for r, c in cells)
        for r, c in cells:
            out[r - top + 1][c] = color
    return out
